/* Keep canonical, snippets and structured data aligned after client-side navigation. */
(function(){
 if(location.pathname.startsWith('/cms'))return;
 let timer,version=0,current=null,frame=null;
 function meta(key,value,property=false){const attr=property?'property':'name';let node=document.head.querySelector(`meta[${attr}="${key}"]`);if(!node){node=document.createElement('meta');node.setAttribute(attr,key);document.head.appendChild(node)}node.content=value||''}
 function details(){
  const draft=window.RENTCAM_PRODUCT_DRAFT;if(!draft&&(!current||new URL(current.canonical).pathname!==location.pathname))return;
  const info=draft||(current?.productInfo?{...current.productInfo,geoSummary:current.productInfo.geoSummary||current.productInfo.summary,aeoQuestion:current.productInfo.question,aeoAnswer:current.productInfo.answer}:null),app=document.getElementById('app');
  if(info&&app&&window.RentcamProductKnowledge){const markup=window.RentcamProductKnowledge.render(info);let section=app.querySelector('[data-search-product-info]');if(markup){if(!section){section=document.createElement('div');section.dataset.searchProductInfo='1';app.appendChild(section);}if(section.dataset.content!==markup){section.dataset.content=markup;section.innerHTML=markup;}}else section?.remove();}
  const business=current?.business,foot=document.querySelector('.footer');if(foot&&business?.address&&!foot.querySelector('[data-search-business]')){const box=document.createElement('address');box.dataset.searchBusiness='1';box.style.cssText='max-width:1180px;margin:auto;padding:0 20px 24px;font-style:normal;font-size:13px';box.textContent=[business.name,business.address.streetAddress,business.address.addressLocality,business.telephone,business.email].filter(Boolean).join(' · ');foot.appendChild(box);}
 }
 function apply(seo){current=seo;document.title=seo.title;meta('description',seo.description);meta('robots',seo.robots);for(const key of ['title','description','url','site_name'])meta('og:'+key,{title:seo.title,description:seo.description,url:seo.canonical,site_name:seo.name}[key],true);meta('og:type','website',true);meta('twitter:title',seo.title);meta('twitter:description',seo.description);meta('og:image',seo.image||'',true);meta('twitter:image',seo.image||'');let canonical=document.querySelector('link[rel="canonical"]');if(!canonical){canonical=document.createElement('link');canonical.rel='canonical';document.head.appendChild(canonical)}canonical.href=seo.canonical;document.querySelectorAll('link[rel="alternate"][hreflang]').forEach(x=>x.href=seo.canonical);document.querySelectorAll('script[data-search-schema],#rentcam-product-schema').forEach(x=>x.remove());for(const data of seo.schema||[]){const node=document.createElement('script');node.type='application/ld+json';node.dataset.searchSchema='1';node.textContent=JSON.stringify({'@context':'https://schema.org',...data});document.head.appendChild(node)}details()}
 async function update(){const path=location.pathname,id=++version;try{const r=await fetch('/api/seo?path='+encodeURIComponent(path),{signal:AbortSignal.timeout(12000)});if(!r.ok)return;const seo=await r.json();if(id===version&&path===location.pathname)apply(seo)}catch(_){/* Keep server-rendered metadata on network failure. */}}
 function schedule(){clearTimeout(timer);timer=setTimeout(update,100)}
 new MutationObserver(()=>{if(frame)return;frame=requestAnimationFrame(()=>{frame=null;details()})}).observe(document.getElementById('app'),{childList:true,subtree:true});
 document.addEventListener('rentcam-route-change',schedule);document.addEventListener('rentcam-cms-updated',schedule);addEventListener('popstate',schedule);schedule();
})();
